// Generated by AI (UnitTest MCP)
//! Structural coverage for the standalone `/agents` dashboard page
//! (task:dde62dd13cfe). `agents_page`/`AppState` live in the private
//! `ackplane-bridge` binary crate, so a real router/DB integration test
//! cannot reach them from here -- `main.rs`'s own `#[cfg(test)] mod tests`
//! already covers the served route and its visibility-gated refresh.
//! This file instead scans the checked-in static asset directly (the same
//! source the route serves via `include_str!`) for the acceptance-critical
//! surface: repository/owner filters, an allow-listed sort control, server-
//! side paging, an accessible live status region, and -- just as
//! important -- the ABSENCE of any new command or mutation surface.

const AGENTS_PAGE: &str = include_str!("../static/agents.html");

#[test]
fn agents_page_exposes_repository_and_owner_filters() {
    assert!(
        AGENTS_PAGE.contains(r#"id="agents-search-repo""#),
        "agents.html must expose a repository filter input"
    );
    assert!(
        AGENTS_PAGE.contains(r#"id="agents-search-owner""#),
        "agents.html must expose an owner filter input"
    );
}

#[test]
fn agents_page_offers_only_the_allow_listed_sort_combinations() {
    // Mirrors handlers/agents.rs::parse_agents_sort's exact allow-list: the
    // three sortable fields, each in both directions, nothing else.
    for allowed in [
        "lease_expires_at:asc",
        "lease_expires_at:desc",
        "repository_id:asc",
        "repository_id:desc",
        "owner_id:asc",
        "owner_id:desc",
    ] {
        assert!(
            AGENTS_PAGE.contains(&format!(r#"value="{allowed}""#)),
            "agents.html's sort control must offer {allowed}"
        );
    }
    assert!(
        AGENTS_PAGE.contains(r#"id="agents-sort""#),
        "agents.html must expose a single sort control"
    );
}

#[test]
fn agents_page_paginates_server_side_rather_than_loading_everything() {
    for required in [
        r#"id="agents-pager-range""#,
        r#"id="agents-prev""#,
        r#"id="agents-next""#,
        "page_size",
        "pageState.page",
    ] {
        assert!(
            AGENTS_PAGE.contains(required),
            "agents.html is missing paging element {required}"
        );
    }
}

#[test]
fn agents_page_reports_status_through_an_accessible_live_region() {
    assert!(
        AGENTS_PAGE.contains(r#"id="agents-status" aria-live="polite""#),
        "agents.html's status line must be an aria-live region so loading/empty/error \
         states are announced to assistive tech"
    );
}

#[test]
fn agents_page_refreshes_only_while_the_tab_is_visible() {
    for required in [
        "function startVisibleRefresh(load, intervalMs)",
        "document.visibilityState === \"visible\"",
        "document.addEventListener(\"visibilitychange\"",
        "startVisibleRefresh(loadAgents, REFRESH_INTERVAL_MS)",
    ] {
        assert!(
            AGENTS_PAGE.contains(required),
            "agents.html is missing bounded visible-only refresh: {required}"
        );
    }
}

#[test]
fn agents_page_reads_the_existing_agents_api_and_nothing_else() {
    assert!(
        AGENTS_PAGE.contains("fetch(`/api/v1/agents?"),
        "agents.html must read the existing GET /api/v1/agents contract"
    );
    // No new command/mutation surface: the only network call this page ever
    // makes is the one GET above, and it never asks fetch for a mutating verb.
    assert_eq!(
        AGENTS_PAGE.matches("fetch(").count(),
        1,
        "agents.html must make exactly one kind of network call (GET /api/v1/agents)"
    );
    for mutating_verb in ["\"POST\"", "\"PUT\"", "\"PATCH\"", "\"DELETE\""] {
        assert!(
            !AGENTS_PAGE.contains(mutating_verb),
            "agents.html must not introduce a mutating request ({mutating_verb})"
        );
    }
}

#[test]
fn agents_page_shares_the_canonical_nav_and_marks_itself_current() {
    assert!(
        AGENTS_PAGE.contains(r#"<nav class="nav" aria-label="Industrial surfaces">"#),
        "agents.html must carry the shared Bridge nav"
    );
    assert!(
        AGENTS_PAGE.contains(r#"<a href="/agents" aria-current="page">Agents</a>"#),
        "agents.html's own nav entry must be marked as the current page"
    );
}

